/// apply) so contract suites and service callers keep working.
#[allow(clippy::result_large_err)]
fn service_op_approve_authorize(
    role: &str,
    response: &crate::domain::refunds::refund_request::dto_response::RefundRequestResponse,
) -> Result<(), String> {
    // op-level `when` transition guard — business semantics apply to every session
if !((response.escalation.as_ref().map(|v| v.to_string()).as_deref() == Some("none"))) {
                return Err("operation `approve`: `when` condition not met (escalation == none)".to_string());
            }
    if role == "api_key" {
                return Ok(());
            }
match role {
        _ => Err("capability `` required (no policy role holds it)".to_string()),
    }
}

